// Icons from open-source icon packs (src/ui/iconpacks, generated by scripts/icon-packs.mjs): Lucide
// by default, the others loaded when chosen in the settings. They are drawn as SVG elements, without
// innerHTML.
import { createContext, h, type JSX } from 'preact';
import { useContext } from 'preact/hooks';
import lucide from './iconpacks/lucide';
import type { IconName } from './iconpacks/names';

export type { IconName };

/** an element of an icon: its tag and attributes */
export type IconNode = [string, Record<string, string>];

export interface IconPack {
  viewBox: string;
  /** the stroke width of outline packs, 0 for packs of filled shapes */
  stroke: number;
  icons: Record<IconName, IconNode[]>;
}

export const DEFAULT_ICON_PACK: IconPack = lucide;

/** the pack chosen in the settings, provided at the root */
export const IconContext = createContext<IconPack>(lucide);

interface IconProps {
  name: IconName;
  size?: number;
  class?: string;
  title?: string;
}

/** an icon of a given pack (the previews of the packs in the settings) */
export function PackIcon({ pack, name, size = 20, class: cls, title }: IconProps & { pack: IconPack }): JSX.Element {
  const s = pack.stroke;
  return (
    <svg
      class={`icon ${cls ?? ''}`}
      width={size}
      height={size}
      viewBox={pack.viewBox}
      fill={s ? 'none' : 'currentColor'}
      stroke={s ? 'currentColor' : undefined}
      stroke-width={s || undefined}
      stroke-linecap={s ? 'round' : undefined}
      stroke-linejoin={s ? 'round' : undefined}
      aria-hidden={title ? undefined : 'true'}
      role={title ? 'img' : undefined}
    >
      {title && <title>{title}</title>}
      {(pack.icons[name] ?? pack.icons.info).map(([tag, a]) => h(tag, a))}
    </svg>
  );
}

export function Icon(props: IconProps): JSX.Element {
  return <PackIcon pack={useContext(IconContext)} {...props} />;
}
